const webhook = $('Webhook').first().json;
const query = webhook.query || {};
const headers = webhook.headers || {};
const token = query.token;

if (!token) {
  return {
    json: {
      success: false,
      valid: false,
      message: 'Не указан токен приглашения'
    }
  };
}

const forwarded = String(
  headers['x-forwarded-for'] || headers['x-real-ip'] || headers['X-Forwarded-For'] || ''
).split(',')[0].trim();
const ip = /^[0-9a-fA-F.:]+$/.test(forwarded) ? forwarded : 'unknown';

return {
  json: {
    token: token,
    safe_ip: ip.replace(/'/g, '')
  }
};

const result = $input.first().json;
const throttleCount = Number(result && result.throttle_count);
if (Number.isFinite(throttleCount) && throttleCount > 600) {
  return {
    json: {
      success: false,
      valid: false,
      error_code: 'RATE_LIMITED',
      message: 'Слишком много запросов. Повторите попытку через несколько минут.'
    }
  };
}

if (!result || !result.id) {
  return {
    json: {
      success: true,
      valid: false,
      message: 'Ссылка-приглашение недействительна или срок её действия истёк'
    }
  };
}

return {
  json: {
    success: true,
    valid: true,
    data: {
      token_id: result.id,
      expires_at: result.expires_at
    },
    message: 'Ссылка-приглашение действительна'
  }
};
